print(array_1)
print(list_1)

# Trying to create an array with multiple data types
try:
    array_2 = arr.array("i", [3, 7, 3, "Interview"])
except Exception as e:
    print(e)
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
array('i', [3, 6, 2, 7, 9, 5])
